\label{thm-nt}
Let \(k\geq1\), and let \(Q_1,\ldots,Q_k\in\mathbb Z[X]\) be pairwise coprime
irreducible polynomials. Put \(Q=Q_1\cdots Q_k\), \(g=\deg Q\),
\(D=\operatorname{Disc}(Q)\), and \(\rho=\rho_Q\), and suppose that \(Q\) has no
fixed prime divisor. Let \(0<\alpha,\delta<1\), \(A,B\geq1\), and
\(0<\varepsilon\leq\alpha\delta/(12g^2)\). If
\(F\in\mathcal M_k(A,B,\varepsilon)\), then, uniformly for
\(x\geq c_0\|Q\|^\delta\) and \(x^\alpha<y\leq x\),
\begin{equation*}\label{eq-nt}
\begin{split}
 &\sum_{\substack{x<n\leq x+y\\Q(n)\ne0}}
 F(|Q_1(n)|,\ldots,|Q_k(n)|)\\
 &\quad\ll y\prod_{p\leq x}\left(1-\frac{\rho(p)}p\right)
 \sum_{n_1\cdots n_k\leq x}
 F(n_1,\ldots,n_k)
 \frac{\rho_{Q_1}(n_1)\cdots\rho_{Q_k}(n_k)}{n_1\cdots n_k}.
\end{split}
\end{equation*}
The constant \(c_0\) depends only on \(g,\alpha,\delta,A,B\), whereas
the implied constant may additionally depend on \(D\).

\label{thm:main}
Assume \(k\geq1\), \(a\in\mathbb Z\setminus\{0\}\), and
\(\boldsymbol\nu\in\mathbb R_{\geq0}^k\).  Let
\(Q_1,\ldots,Q_k\in\mathbb Z[X]\) be pairwise coprime irreducible
polynomials, put
\[
 Q=Q_1\cdots Q_k,\qquad g=\deg Q,\qquad
 D=\operatorname{Disc}(Q),\qquad \rho=\rho_Q,
\]
and assume that \(Q\) is primitive.  Assume
\(0<\alpha,\delta<1\), \(A,B\geq1\), and let 
\begin{equation*}\label{eq:epsilon-range}
 0<\varepsilon
 \leq\frac{\alpha}{100g(g+1/\delta)}
\end{equation*}
and \(\mathcal{M}_k(A,B,\varepsilon)\) be defined as in Section~\ref{section1}.

If  \(F\in\mathcal M_k(A,B,\varepsilon)\), then, uniformly for
\begin{equation}\label{eq:xyrange}
 x\geq c_0\|Q\|^\delta,\qquad x^\alpha<y\leq x,    
\end{equation}
we have
\begin{equation}\label{eq:main-theorem}
\begin{split}
 &\sum_{\substack{x<n\leq x+y\\Q(n)\neq0}}
 F(|Q_1(n)|,\ldots,|Q_k(n)|)
 \prod_{j=1}^k|\operatorname{Kl}(a;|Q_j(n)|)|^{\nu_j}\\
 &\quad\ll
 y\prod_{g<p\leq x}\left(1-\frac{\rho(p)}p\right)
 \sum_{d_1\cdots d_k\leq x}
 F(d_1,\ldots,d_k)H_{a,\boldsymbol\nu}(d_1,\ldots,d_k).
\end{split}
\end{equation}
Here the constant \(c_0\) and the implied constant depend only on
\(\boldsymbol\nu,g,k,\alpha,\delta,A,B\).

\label{cor:discriminant}
Under the assumption of Theorem \ref{thm:main},  for any $x,y$ satisfying \eqref{eq:xyrange},
\begin{equation}\label{eq:discriminant-separated}
\begin{split}
 &\sum_{\substack{x<n\leq x+y\\Q(n)\neq0}}
 F(|Q_1(n)|,\ldots,|Q_k(n)|)
 \prod_{j=1}^k|\operatorname{Kl}(a;|Q_j(n)|)|^{\nu_j}\\
 &\quad\ll
 \Delta_D(a,\boldsymbol\nu,F)\,y
 \prod_{g<p\leq x}\left(1-\frac{\rho(p)}p\right)
 \sum_{\substack{d_1\cdots d_k\leq x\\
                  (d_1\cdots d_k,D)=1\\
                  (d_i,d_j)=1\ (i\neq j)}}
 F(\mathbf d)H_{a,\boldsymbol\nu}(\mathbf d),
\end{split}
\end{equation}
where  $ \Delta_D(a,\boldsymbol\nu,F)$ (defined in \eqref{eq:Delta-D} with $S=\operatorname{Disc} Q$) satisfies \begin{equation*}\label{eq:Delta-D-finite}
 \Delta_D(a,\boldsymbol\nu,F)
 \asymp
 \prod_{p\mid D}
 \left(
  1+\sum_{1\leq|\boldsymbol\ell|<8g}
  T_{a,\boldsymbol\nu,F}(p^{\boldsymbol\ell})
 \right).
\end{equation*}
In fact, 
\begin{equation*}\label{eq:Delta-D-bound}
 1\leq\Delta_D(a,\boldsymbol\nu,F)
 \leq\prod_{p\mid D}\left(1+\frac Cp\right)
 \leq\left(\frac{|D|}{\varphi(|D|)}\right)^C.
\end{equation*}
The implied constants in $\asymp$  and the constant \(C\ge 1\) depend on \(\boldsymbol\nu,g,k,A,B\) only, while the implied $\ll$-constant in \eqref{eq:discriminant-separated} depends only on \(\boldsymbol\nu,g,k,\alpha,\delta,A,B\).

\label{cor:Henriot-cor2}
For a prime \(p\), an
integer \(\ell\geq1\), and \(1\leq j\leq k\), write
\[
 \mathbf p_j^\ell:=(1,\ldots,1,p^\ell,1,\ldots,1),
\]
where \(p^\ell\) occupies the \(j\)-th coordinate in \(\mathbf p_j^\ell\). 
Under the assumptions of Theorem \ref{thm:main} holds, for any $x,y$ satisfying \eqref{eq:xyrange},
\begin{equation*}\label{eq:Henriot-cor2-euler}
\begin{split}
 &\sum_{\substack{x<n\leq x+y\\Q(n)\neq0}}
 F(|Q_1(n)|,\ldots,|Q_k(n)|)
 \prod_{j=1}^k|\operatorname{Kl}(a;|Q_j(n)|)|^{\nu_j}\\
 &\quad\ll 
 \Delta_S(a,\boldsymbol\nu,F)\,y
 \prod_{g<p\leq x}\left(1-\frac{\rho(p)}p\right)
 \prod_{\substack{p\le x\\p\nmid S}}
 \left(
 1+
 \sum_{j=1}^k
 G_F(\mathbf p_j^1)
 \frac{\rho_{Q_j}(p)
       \lambda_{a,\nu_j}(p)}{p}
 \right),
\end{split}
\end{equation*}
where \(S:= \prod_{p\in \mathcal{S}} p\).  Moreover, we have
\begin{equation}\label{eq:vartheta-bad}
1\le  \Delta_S(a,\boldsymbol\nu,F)\le \left(\frac{S}{\varphi(S)}\right)^C.
\end{equation}
The implied $\ll$-constant has the same dependencies as in Theorem~\ref{thm:main} and the constant \(C\) is the same as the one in Corollary~\ref{cor:discriminant}.

\label{thm:prime-variable}
Under the same assumptions as in Theorem~\ref{thm:main}, and suppose that
\(Q(0)\ne0\), and 
\begin{equation}\label{eq:prime-epsilon-range}
 0<\varepsilon
 \leq\frac{\alpha}
 {100(g+1)(g+1+1/\delta)},
\end{equation}
we have, uniformly for \(x,y\) in the same range as \eqref{eq:xyrange}, 
\begin{equation}\label{eq:prime-variable}
\begin{split}
 &\sum_{\substack{x<p\leq x+y\\Q(p)\ne0}}
 F(|Q_1(p)|,\ldots,|Q_k(p)|)
 \prod_{j=1}^k|\operatorname{Kl}(a;|Q_j(p)|)|^{\nu_j}\\
 &\quad\ll
 \frac{|Q(0)|}{\varphi(|Q(0)|)}
 \frac{y}{\log x}\,
 \Delta_S(a,\boldsymbol\nu,F)
 \prod_{g<p\leq x}\left(1-\frac{\rho(p)}p\right)
 \prod_{\substack{p\leq x\\p\nmid S}}
 \left(
 1+\sum_{j=1}^k
 G_F(\mathbf p_j^1)
 \frac{\rho_{Q_j}(p)\lambda_{a,\nu_j}(p)}p
 \right).
\end{split}
\end{equation}
The constant \(c_0\) and the implied constant have the same
dependencies as in Theorem~\ref{thm:main}.

\label{cor:normalized}
Let $0<\alpha, \delta<1$, \(k\in \mathbb N\) and 
\(z_j>0\) be any fixed number for \(1\leq j\leq k\). Under the assumption of Theorem \ref{thm:main} for $Q_j$ \((1\le j\le k)\),  
\begin{equation*}\label{eq:normalized-moment}
 \sum_{\substack{x<n\leq x+y\\Q(n)\neq0}}
 \prod_{j=1}^k
 z_j^{\omega(|Q_j(n)|)}
 |\operatorname{Kl}(a;|Q_j(n)|)|^{\nu_j}
 \ll
 y(\log x)^{\sum_{j=1}^k(z_j\mathfrak s(\nu_j)-1)}
\end{equation*}
holds uniformly in
\(a\in\mathbb Z\setminus\{0\}\), for any \(x\geq c_0\|Q\|^\delta\) and \(x^\alpha<y\leq x\), where the constant $c_0$  and the implied constant  depend on $\boldsymbol\nu,\mathbf z,Q_1,\ldots,Q_k,\alpha,\delta$ only.

\label{thm:lower}
Let \(z,\nu,A>0\) be fixed. For all sufficiently large \(x\) in terms of
\(A,z,\nu\), uniformly for nonzero integers \(a\) with \(|a|\leq x^A\),
\begin{equation*}\label{eq:lower-bound}
 \sum_{\substack{x/2<n\leq x\\n\ \mathrm{squarefree}\\(n,2a)=1}}
 z^{\omega(n)}|\operatorname{Kl}(a;n)|^\nu
 \gg_{A,z,\nu}
 \prod_{p\mid a}\left(1+\frac{z\mathfrak s(\nu)}p\right)^{-1}
 x(\log x)^{z\mathfrak s(\nu)-1}.
\end{equation*}

\label{cor:Kl-large-values}
Let \(a\ne0\) and \(B\geq0\) be fixed. Then
\[
 \lim_{x\to\infty}
 \frac{\log\mathbb P_x\!\left(\mathcal L_{a,B}(x)\right)}{\log\log x}
 =-I(B).
\]

\label{thm:LS}
Let \(A>0\) be fixed. There exists a constant $x_0(A)$ depending on $A$ such that uniformly for all $x\ge x_0(A)$ and  nonzero integers \(u\) with \(|u|\leq x^A\),
\[
 \prod_{p\mid u}\left(1+\frac{1}{p}\right)^{-1}
 \ll \frac{1}{\log x}\sum_{n\leq x}\frac{|S(u,u;n)|^2}{n^2}
 \ll \tau(|u|)^2,
\]
where \(\tau\) is the divisor function, the first implied constant
depends only on \(A\), and the second is absolute. The upper bound
holds for every nonzero integer \(u\).

\label{cor:spectral-variance}
Let \(h,\psi,\delta\) be as above, with \(\widehat h\not\equiv 0\) in  \(((1+\delta)^{-1},1)\). Then uniformly for \(L\) in the range
\eqref{eq:spectral-window}, we have
\begin{equation}\label{eq:spectral-variance-order}
 \Sigma_h(T,L)\asymp\frac{T}{L}.
\end{equation}
Moreover, 
\begin{equation}\label{eq:spectral-mean-square}
 \int_T^{2T}S(t)^2\,dt\gg\frac{T^2}{\log T}.
\end{equation}
In particular,
\[
 S(T)=\Omega \bigg(\sqrt{\frac{T}{\log T}}\bigg),
\]
where the implied constants in these estimates depend only on \(h,\psi,\delta\).

\label{lem:lambda}
Let \(\nu\geq0\) be fixed. For \(\ell \geq 1\), \(\lambda_{a,\nu}(2^\ell)\leq 2^{\frac52\nu}\) and  
\begin{equation}\label{eq:lambda-power}
 \lambda_{a,\nu}(p^\ell)\leq  2^\nu
 \qquad(p \ \textrm{odd}).
\end{equation}
If \(p\nmid2a\), then
\begin{equation}\label{eq:lambda-prime}
 \lambda_{a,\nu}(p)=\mathfrak s(\nu)+O_\nu(p^{-1/8}),
\end{equation}
uniformly in \(a\bmod p\). For a prime \(p\) and an integer \(a\), we also have
\begin{equation}\label{eq:lambda-prime-upper}
 \lambda_{a,\nu}(p)\leq\mathfrak s(\nu)+O_\nu(p^{-1/8}).
\end{equation}

\label{lem:lifting}
Let \(p\) be a prime, and let \(R\in\mathbb Z[X]\) be nonconstant. Suppose
\(p\nmid\operatorname{lc}(R)\operatorname{Disc}(R)\). For any integer \(\ell\geq1\) and real
\(\nu\geq0\),
\begin{equation*}
 \sum_{\substack{r\bmod p^{2\ell}\\p^\ell\parallel R(r)}}
 \left|
 \operatorname{Kl} \left(
 a\,\overline{R(r)/p^\ell}^{2};p^\ell
 \right)
 \right|^\nu
 =\rho_R(p)\varphi(p^\ell)\lambda_{a,\nu}(p^\ell).
\end{equation*}

\label{lem:H-properties}
The function \(H_{a,\boldsymbol\nu}:\mathbb N^k\to\mathbb R_{\geq0}\) is multiplicative,
in the sense that
\[
 H_{a,\boldsymbol\nu}(\mathbf{de})
 =H_{a,\boldsymbol\nu}(\mathbf d)H_{a,\boldsymbol\nu}(\mathbf e)
\]
when \((d_1\cdots d_k,e_1\cdots e_k)=1\), where \(\mathbf{d}=(d_1,\ldots, d_k)\), \(\mathbf{e}=(e_1,\ldots, e_k)\) and \(\mathbf{de}:=(d_1e_1,\ldots, d_ke_k)\).  Moreover,
\begin{align}\label{eq:H-comparison}
 H_{a,\boldsymbol\nu}(\mathbf d)
 & \le
 \frac{\rho(d_1\cdots d_k)}{d_1\cdots d_k} \prod_{j=1}^k \big(2^{\omega(d_j)}\kappa(v_2(d_j))\big)^{\nu_j}. 
\end{align}
In particular, we have  for \(p^{\boldsymbol\ell}=(p^{\ell_1},\ldots,p^{\ell_k})\) where \({\boldsymbol\ell}=(\ell_1,\ldots,\ell_k)\),
\begin{equation}\label{eq:H-fair-2}
    H_{a,\boldsymbol\nu}(2^{\boldsymbol\ell})\le    2^{\frac52|{\boldsymbol\nu}|} 
    \frac{\rho_{Q}(2^{|{\boldsymbol\ell}|})}{2^{|{\boldsymbol\ell}|}}
    \qquad \mbox{ and }\qquad 
    H_{a,\boldsymbol\nu}(p^{\boldsymbol\ell})\le    2^{|{\boldsymbol\nu}|} 
    \frac{\rho_{Q}(p^{|{\boldsymbol\ell}|})}{p^{|{\boldsymbol\ell}|}}\quad (p \ \textrm{odd}),
  \end{equation}
and for \(\mathbf{d}=\mathbf p_j^\ell:=(1,\ldots,1,p^\ell,1,\ldots,1)\), 
\begin{equation}\label{eq:H-fair}
    H_{a,\boldsymbol\nu}(\boldsymbol{2}_j^\ell)\le    2^{\frac52\nu_j}
    \frac{\rho_{Q_j}(2^\ell)}{2^\ell}
    \qquad \mbox{ and }\qquad 
    H_{a,\boldsymbol\nu}(\mathbf p_j^\ell)
    \le  2^{\nu_j}
    \frac{\rho_{Q_j}(p^\ell)}{p^\ell} \quad (p \ \textrm{odd}).
  \end{equation}

\label{lem:local-majorant}
  Assume \(p\nmid D\) and  let \({\boldsymbol\ell}=(\ell_1,\ldots,\ell_k)\in \mathbb N_0^k\). 

  Case (1): 
    \(\ell_i,\ell_j>0\) for some $i\neq j$:  
  \[
  H_{a,\boldsymbol\nu}(p^{\ell_1},\ldots,p^{\ell_k})=0.
  \]
  Consequently, for \(\mathbf d\in\mathbb N^k\) satisfying
\((d_1\cdots d_k,D)=1\), \(H_{a,\boldsymbol\nu}(\mathbf d)\neq 0\) can happen only when \((d_i,d_j)=1\) for all $i\neq j$, and in this case, 
  \begin{equation}\label{eq:H-majorant-coprime-D}
    H_{a,\boldsymbol\nu}(\mathbf d) = \prod_{j=1}^k H_{a,\boldsymbol\nu}(1,\ldots,d_j,\ldots,1)=  \prod_{j=1}^k \prod_{p^\ell \| d_j} H_{a,\boldsymbol\nu}(1,\ldots,p^\ell,\ldots,1).
  \end{equation}

  Case (2): \(\ell_i=0\) for all \(i\neq j\): 
  \begin{equation}\label{eq:H-good}
    H_{a,\boldsymbol\nu}(1,\ldots,p^\ell,\ldots,1)
    = (1-p^{-1})\rho_{Q_j}(p)
    \frac{\lambda_{a,\nu_j}(p^\ell)}{p^\ell}
    \qquad \mbox{if \(p\nmid\operatorname{lc}(Q)\)D}.
  \end{equation}

\label{lem:T-Delta} 
Let \(T_{a,\boldsymbol\nu,F}(\mathbf d)=  G_F(\mathbf d)H_{a,\boldsymbol\nu}(\mathbf d)\) and \(\Delta_p(a,\boldsymbol\nu,F)\) be defined as in \eqref{eq:T-Delta-def}. 
\begin{enumerate}
\item  \(T_{a,\nu,F}\) is submultiplicative, and  
\begin{align}\label{eq:moderate}
 \sum_{|\boldsymbol\ell|\geq s}T_{a,\nu,F}(p^{\boldsymbol\ell})
 &\ll_{g,k,A,B} \eta_2(p)^{|\boldsymbol\nu|} p^{-\max(1,s/(4g))}\nonumber\\ &\ll_{\boldsymbol\nu,g,k,A,B} p^{-\max(1,s/(4g))},
\end{align}
where \(\eta_2(p)= 2^{5/2}\) if \(p=2\), or \(2\) otherwise. 
\item 
\[\Delta_p(a,\boldsymbol\nu,F)  = \left(1+O(p^{-2})\right)
 \Big(1+\sum_{1\leq|\boldsymbol\ell|<8g}
 T_{a,\nu,F}(p^{\boldsymbol\ell})\Big) 
\]
where the $O$-term denotes a nonnegative quantity and the implied $O$-constant depends only on \(\boldsymbol\nu,g,k,A,B\). 
\end{enumerate}
Hence  
    \begin{equation}\label{eq:Delta}
        1\le \Delta_p(a,\boldsymbol\nu,F) \le  1+Cp^{-1}
    \end{equation}     
for some positive constant $C$ depending only on  \(\boldsymbol\nu,g,k,A,B\).

For \(1\leq j\leq k\), we write \(d_j=b_jc_j\) with
\(b_j\mid D^\infty\) and \((c_j,D)=1\).
Since \((b_1\cdots b_k,c_1\cdots c_k)=1\),
submultiplicativity \eqref{submultiplicativity} and the multiplicativity of \(H_{a,\boldsymbol\nu}\) yield
\begin{equation*}
\begin{aligned}
 \sum_{d_1\cdots d_k\leq x}F(\mathbf d)H_{a,\boldsymbol\nu}(\mathbf d)&\leq
 \bigg(\sum_{b_1\cdots b_k\mid D^\infty}
 T_{a,\boldsymbol\nu,F}(\mathbf b)\bigg)
 \sum_{\substack{c_1\cdots c_k\leq x\\
                  (c_1\cdots c_k,D)=1}}
 F(\mathbf c)H_{a,\boldsymbol\nu}(\mathbf c)\\
 &\leq
 \Delta_D(a,\boldsymbol\nu,F)
 \sum_{\substack{c_1\cdots c_k\leq x\\
                  (c_1\cdots c_k,D)=1}}
 F(\mathbf c)H_{a,\boldsymbol\nu}(\mathbf c).
\end{aligned}
\end{equation*}
Here we further apply the submultiplicativity to the prime power factors
of \(\mathbf b\) and obtain
\[
 \sum_{b_1\cdots b_k\mid D^\infty}T_{a,\boldsymbol\nu,F}(\mathbf b)
 \leq\prod_{p\mid D}
 \bigg(1+\sum_{|\boldsymbol\ell|\geq1}
 T_{a,\boldsymbol\nu,F}(p^{\boldsymbol\ell})\bigg)
 =\Delta_D(a,\boldsymbol\nu,F).
\]
As \(\Delta_D(a,\boldsymbol\nu,F)= \prod_{p|D} \Delta_p(a,\boldsymbol\nu,F)\), the proof is complete with Lemma~\ref{lem:T-Delta} and the last inequality of \eqref{eq:Delta-D-finite} makes use of
\(1+Cp^{-1}\leq(1-p^{-1})^{-C}\).

\label{lem:lower-small-mass}
We have
\[
 \mathcal H_a:=\sum_{d\in\mathcal D}
 \frac{z^{\omega(d)}\lambda_{a,\nu}(d)}d
 \gg
 (\log x)^{z\mathfrak s(\nu)}
 \prod_{p\mid2a}\left(1+\frac{z\mathfrak s(\nu)}p\right)^{-1},
\]
where the implied constant depends only on \(z,\nu\).

Let \(\mathcal B\) be the set of squarefree integers \(d\) with
\(P^+(d)\leq Z\) and \((d,2a)=1\), and denote
\[
 \mathcal E_a=\sum_{d\in\mathcal B}
 \frac{z^{\omega(d)}\lambda_{a,\nu}(d)}d
 =\prod_{\substack{p\leq Z\\p\nmid2a}}
 \left(1+\frac{z\lambda_{a,\nu}(p)}p\right).
\]
For each prime \(p\leq Z\) with \(p\nmid2a\), by multiplicativity, we have
\[
\begin{aligned}
 \sum_{\substack{d\in\mathcal B\\p\mid d}}
 \frac{z^{\omega(d)}\lambda_{a,\nu}(d)}d
 &=\frac{z\lambda_{a,\nu}(p)}p
 \prod_{\substack{q\leq Z\\q\nmid2a,\ q\ne p}}
 \left(1+\frac{z\lambda_{a,\nu}(q)}q\right)\\
 &\leq\frac{z\lambda_{a,\nu}(p)}p\,\mathcal E_a.
\end{aligned}
\]
Note that \(\log d=\sum_{p\mid d}\log p\) and
\(\omega(d)=\sum_{p\mid d}1\) for \(d\in\mathcal B\).
For \(d\in\mathcal B\setminus\mathcal D\), one has
\(d>x^{1/30}\) or \(\omega(d)>C\log\log x\). Hence
\begin{equation}\label{eq:EH}
	\begin{aligned}
		\frac{\mathcal E_a-\mathcal H_a}{\mathcal E_a}
		&\leq\frac1{\mathcal E_a}
		\sum_{d\in\mathcal B}
		\frac{z^{\omega(d)}\lambda_{a,\nu}(d)}d
		\left(\frac{30\log d}{\log x}
		+\frac{\omega(d)}{C\log\log x}\right)\\
		&\leq
		\sum_{\substack{p\leq Z\\p\nmid2a}}
		\frac{z\lambda_{a,\nu}(p)}p
		\left(\frac{30\log p}{\log x}
		+\frac1{C\log\log x}\right).
	\end{aligned}
\end{equation}
Using \eqref{eq:lambda-prime}, the relation
\(\log Z=(\log x)/(30C)\), and Mertens' estimates
\[
 \sum_{p\leq Z}\frac{\log p}p=\log Z+O(1),
 \qquad
 \sum_{p\leq Z}\frac1p=\log\log Z+O(1),
\]
we bound the last sum in \eqref{eq:EH} by
\[
 \frac{30z\mathfrak s(\nu)\log Z+O_{z,\nu}(1)}{\log x}
 +\frac{z\mathfrak s(\nu)\log\log Z+O_{z,\nu}(1)}{C\log\log x}
 =\frac{2z\mathfrak s(\nu)}C+o_{z,\nu}(1).
\]
Since \(2z\mathfrak s(\nu)/C<1/2\), we have
\(\mathcal H_a\gg_{z,\nu}\mathcal E_a\). Moreover, by \eqref{eq:lambda-prime} and Mertens' formula, we get
\begin{equation*}
	\mathcal E_a\gg\prod_{\substack{p\leq Z\\p\nmid2a}}
	\left(1+\frac{z\mathfrak s(\nu)}p\right)\gg_{z,\nu} (\log Z)^{z\mathfrak s(\nu)}
	\prod_{p\mid2a}\left(1+\frac{z\mathfrak s(\nu)}p\right)^{-1}.
\end{equation*}
This proves the lemma.

For each \(p\in\mathcal P\), we split the sum over \(m\) into
nonzero residue classes modulo \(p\) and get
\begin{equation}\label{eq:lower-residue-decomposition}
\begin{aligned}
 \sum_{\substack{Y/2<pm\leq Y\\
                  \theta_{p,a\bar m^2}\in I}}f(m)
 &=\sum_{\substack{1\leq r<p\\\theta_{p,a\bar r^2}\in I}}
       \sum_{\substack{Y/2<pm\leq Y\\
                       m\equiv r\,({\rm mod}\,p)}}f(m)\\
 &=\frac1{p-1}
       \sum_{\substack{1\leq r<p\\\theta_{p,a\bar r^2}\in I}}
       \sum_{Y/2<pm\leq Y}f(m)\\
 &\quad+
       \sum_{\substack{1\leq r<p\\\theta_{p,a\bar r^2}\in I}}
       \bigg(
       \sum_{\substack{Y/2<pm\leq Y\\
                       m\equiv r\,({\rm mod}\,p)}}f(m)
       -\frac1{p-1}\sum_{Y/2<pm\leq Y}f(m)
       \bigg)\\
&= \Sigma_{1,p}+ \Sigma_{2,p}, \mbox{ say}.
\end{aligned}
\end{equation}
By \eqref{eq:a-ST-discrepancy} and the nonnegativity of \(f\),
the sum of $\Sigma_{1,p}$ over \(p\in\mathcal P\) equals
\[
\sum_{p\in\mathcal P}
  \left(\mu_{\rm ST}(I)+O(p^{-\frac{1}{8}})\right)
  \sum_{Y/2<pm\leq Y}f(m)=\left(\mu_{\rm ST}(I)+O(P^{-\frac{1}{8}})\right)
  \sum_{p\in\mathcal P}\sum_{Y/2<pm\leq Y}f(m),
\]
uniformly in \(a\) and \(I\).

The sum  of $\Sigma_{2,p}$ over \(p\in\mathcal P\) is, by the Cauchy--Schwarz inequality, 
\[
\begin{aligned}
 &\ll(P\#\mathcal P)^{\frac{1}{2}}
\bigg(\sum_{p\in\mathcal P}\sideset{}{^*}\sum_{r\bmod p}
\bigg|
\sum_{\substack{Y/2<pm\leq Y\\
		m\equiv r\,({\rm mod}\,p)}}f(m)
-\frac1{p-1}\sum_{Y/2<pm\leq Y}f(m)
\bigg|^2\bigg)^{\frac{1}{2}}\\
& \ll(\log Y)(P\#\mathcal P)^{\frac{1}{2}}
\left(\frac NP+P\right)^{\frac{1}{2}}
\left(\sum_m|f(m)|^2\right)^{\frac{1}{2}},
\end{aligned}
\]
where we used \cite[Lemma~2.5]{FM-2003} in the last step.
Combining the two estimates proves the lemma.

Selberg's identity \cite[(4.10)]{Iwaniec-1997} yields
\begin{equation}\label{eq:Selberg-Id}
	S(u,u;n)=\sum_{d\mid (|u|,n)} \sqrt{nd}\operatorname{Kl}\bigg(\frac{u^2}{d^2};\frac{n}{d}\bigg).
\end{equation}
By the Cauchy--Schwarz inequality, we thus get
\begin{equation}\label{eq:LS-Cauchy}
 \sum_{n\leq x}\frac{|S(u,u;n)|^2}{n^2}
 \leq
 \tau(|u|)
 \sum_{\substack{d\mid |u|\\d\leq x}}
 \sum_{q\leq x/d}
 \frac{\left|\operatorname{Kl}\!\left(\frac{u^2}{d^2};q\right)\right|^2}{q}.
\end{equation}
The upper bound in Corollary~\ref{cor:moment-order}, with
\(z=1\) and \(\nu=2\), asserts that
\[
\sum_{n\leq x}|\operatorname{Kl}(a;n)|^2\ll x
\]
uniformly for \(a\ne0\). This estimate, together with partial
summation in \eqref{eq:LS-Cauchy}, proves the required upper bound.

For the lower bound, suppose that \(0<|u|\leq x^A\). Theorem~\ref{thm:lower} with \(z=1\) and \(\nu=2\) yields
\begin{equation}\label{eq:Kl-sec-lower}
	 \sum_{\substack{n\leq y\\(n,u)=1}}|\operatorname{Kl}(u^2;n)|^2
	\gg y\prod_{p\mid u}\left(1+\frac{1}{p}\right)^{-1}
\end{equation}
for any $\sqrt{x}\leq y\leq x$, where the implied constant depends only on \(A\).
For \((n,u)=1\), Selberg's identity \eqref{eq:Selberg-Id} reduces to
\(S(u,u;n)=\sqrt n\,\operatorname{Kl}(u^2;n)\). Thus, by partial summation, it follows from \eqref{eq:Kl-sec-lower} that
\[
\begin{aligned}
 \sum_{n\leq x}\frac{|S(u,u;n)|^2}{n^2}
 &\geq\sum_{\substack{n\leq x\\(n,u)=1}}
 \frac{|\operatorname{Kl}(u^2;n)|^2}{n}\\
 &\geq\int_{\sqrt x}^{x}\frac{1}{y^2}
 \sum_{\substack{n\leq y\\(n,u)=1}}|\operatorname{Kl}(u^2;n)|^2\,dy\\
 &\gg(\log x)\prod_{p\mid u}\left(1+\frac{1}{p}\right)^{-1}.
\end{aligned}
\]

Since the shifts are distinct, the polynomials
\(Q_j(X)=X+h_j\) are irreducible and pairwise coprime. Corollary~\ref{cor:normalized}
with \(z_j=2^{-\nu_j}\) therefore yields
\[
 \sum_{x<n\leq2x}
 \prod_{j=1}^s
 \left(\frac{|\operatorname{Kl}(a;n+h_j)|}{2^{\omega(n+h_j)}}\right)^{\nu_j}
 \ll x(\log x)^{\sum_{j=1}^s2^{-\nu_j}\mathfrak s(\nu_j)-s},
\]
where the implied constant depends only on \(\boldsymbol\nu,\mathbf h\). The dyadic argument completes the proof.
